import os,zipfile,re,html
root='documents/matters'
kw=['Funds & Asset Management','Funds and Asset Management','LPAC','LP Advisory Committee','Limited Partner Advisory Committee','advisory committee','LPA','limited partnership agreement','executed','fully executed','signed']
out='scratch/docx_keyword_sources.txt'
with open(out,'w',encoding='utf-8') as w:
