       m=re.search(re.escape(k),x,re.I); s=max(0,m.start()-120); e=min(len(x),m.end()+220)
       found.append(k+' => '+x[s:e])
    if found:
      w.write('SOURCE: '+p+'\n')
      for f in found: w.write(f+'\n')
      w.write('\n')
   except: pass
print('wrote',out)
