import os,zipfile,re,html,collections
root='documents/matters'; d=collections.defaultdict(set)
for dp,_,fs in os.walk(root):
 for fn in fs:
  if not fn.endswith('.docx'): continue
  p=os.path.join(dp,fn)
  try:
   with zipfile.ZipFile(p) as z: x=z.read('word/document.xml').decode('utf-8','ignore')
   x=html.unescape(re.sub(r'<[^>]+>',' ',x)); x=re.sub(r'\s+',' ',x)
